yakit.AutoInitYakit()

yakit.Info("域名Whois历史查询任务已启动")

domain = cli.String("domain")

if str.IsHttpURL(domain){
    domain = str.ReplaceAll(domain, "http://", "")
    domain = str.ReplaceAll(domain, "https://", "")
}
if str.Contains(domain, "/"){
    domain = str.Split(domain, "/")[0]
}

func postRequest(url){
    url = "https://whois.4.cn/api/whoishistory?domain=" + url
    rsp, err := http.Get(
        url,
        http.header("User-Agent", "Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/80.0.3987.87 Safari/537.36"),
    )
    die(err)
    raw, err := io.ReadAll(rsp.Body)
    die(err)
    yakit.Info("域名Whois历史查询任务已完成")
    return string(raw)
}

yakit.EnableTable("域名Whois历史查询结果", ["注册人姓名", "手机号", "邮箱", "组织", "注册商", "域名服务器", "注册时间", "过期时间"])
outputTable = func(Name, Phone, Email, Organization, Registrars, Nameserver, Createdate, Expiredate) {
    data = make(map[string]var)
    data["注册人姓名"] = Name
    data["手机号"] = Phone
    data["邮箱"] = Email
    data["组织"] = Organization
    data["注册商"] = Registrars
    data["域名服务器"] = Nameserver
    data["注册时间"] = Createdate
    data["过期时间"] = Expiredate
    yakit.TableData("域名Whois历史查询结果", data)
}

resp = postRequest(domain)
data = json.loads(resp)["data"]["results"]
if len(data) != 0{
    for _,element = range data{
        outputTable(element.owner_name, element.owner_phone, element.owner_email, element.owner_org, element.registrars, str.Join(element.nameserver, "\n"), element.create_date, element.expire_date)
    }
}else{
    outputTable("Null", "Null", "Null", "Null", "Null", "Null", "Null", "Null")
}
